//
//  UITestSupport.swift
//  LatchkeyUITests
//
//  Helpers shared by the suites.
//

import XCTest

/// The harnesses' plain-HTTP control ports, over loopback.
///
/// One implementation, because there were three: each suite had its own private
/// `get`/`post` pair, `get` checked the status code in all three and `post`
/// checked it in none. A `POST /__mode?front=502` aimed at the wrong server
/// therefore returned 404, threw nothing, and the test that depended on it
/// asserted against a perfectly healthy dashboard — then hung for two minutes
/// waiting for an error page that was never going to appear. A control call
/// that does nothing must fail the test that made it.
enum HarnessControl {
    /// Thrown for any non-2xx. Carries the URL because the usual cause is a
    /// path or a port that does not exist on the server being asked.
    struct BadStatus: Error, CustomStringConvertible {
        let method: String
        let url: String
        let status: Int
        let body: String
        var description: String {
            "\(method) \(url) answered \(status), not 2xx"
                + (body.isEmpty ? "" : ": \(body.prefix(200))")
        }
    }

    static func get(_ url: String, timeout: TimeInterval = 5) async throws -> Data {
        try await send("GET", url, timeout: timeout)
    }

    @discardableResult
    static func post(_ url: String, timeout: TimeInterval = 5) async throws -> Data {
        try await send("POST", url, timeout: timeout)
    }

    private static func send(_ method: String, _ url: String,
                             timeout: TimeInterval) async throws -> Data {
        var request = URLRequest(url: URL(string: url)!, timeoutInterval: timeout)
        request.httpMethod = method
        let (data, response) = try await URLSession.shared.data(for: request)
        let status = (response as? HTTPURLResponse)?.statusCode ?? 0
        guard (200...299).contains(status) else {
            throw BadStatus(method: method, url: url, status: status,
                            body: String(decoding: data, as: UTF8.self))
        }
        return data
    }
}

/// Which harness instance a run talks to, and on which ports (F14).
///
/// Two suite runs at once need two harnesses, so the ports are not constants:
/// the suite scripts read an instance's ports from `make ports` and hand them
/// to xcodebuild as `TEST_RUNNER_LATCHKEY_<NAME>`, which reach this process as
/// `LATCHKEY_<NAME>`. Absent, each is the Makefiles' default (instance 0),
/// which is what a single run has always used.
enum HarnessInstance {
    static let id = ProcessInfo.processInfo.environment["LATCHKEY_HARNESS_INSTANCE"] ?? "0"

    static func port(_ name: String, default fallback: Int) -> Int {
        guard let raw = ProcessInfo.processInfo.environment["LATCHKEY_\(name)"] else { return fallback }
        guard let port = Int(raw), (1...65535).contains(port) else {
            preconditionFailure("LATCHKEY_\(name)=\(raw) is not a port")
        }
        return port
    }

    /// Fails unless the server behind `stateURL` (a control endpoint whose
    /// JSON carries `instance`) is this run's instance. Ports are the only
    /// thing keeping two instances apart, and a run that reached its sibling
    /// would change modes under the sibling's tests and pass on its journal.
    static func assertIsOurs(_ stateURL: String) async throws {
        let state = try JSONSerialization.jsonObject(
            with: try await HarnessControl.get(stateURL)) as? [String: Any]
        let theirs = state?["instance"] as? String ?? "<none>"
        guard theirs == id else { throw WrongInstance(url: stateURL, theirs: theirs, ours: id) }
    }

    struct WrongInstance: Error, CustomStringConvertible {
        let url: String, theirs: String, ours: String
        var description: String { "\(url) is harness instance \(theirs), not this run's \(ours)" }
    }
}

extension XCUIElement {
    /// `waitForExistence`, polled every 100 ms. XCTest's own wait first looks
    /// about a second after it starts and then once a second (F14 §4.1,
    /// measured: 1.07 s for an element already on screen), so every wait for
    /// something that is there cost a second, dozens of times per suite. Same
    /// answer, same timeout; only the polling is finer.
    @MainActor
    func appears(within timeout: TimeInterval) -> Bool {
        let deadline = Date().addingTimeInterval(timeout)
        while !exists {
            if Date() >= deadline { return false }
            Thread.sleep(forTimeInterval: 0.1)
        }
        return true
    }

    /// `waitForNonExistence`, polled the same way.
    @MainActor
    func disappears(within timeout: TimeInterval) -> Bool {
        let deadline = Date().addingTimeInterval(timeout)
        while exists {
            if Date() >= deadline { return false }
            Thread.sleep(forTimeInterval: 0.1)
        }
        return true
    }

    /// Taps this element once it exists, the app has no presentation or
    /// dismissal in progress, and it is hittable; fails the test otherwise.
    ///
    /// `tap()` alone is not enough, twice over. An element is in the tree from
    /// the first frame of the sheet it is on, while UIKit still drops touches,
    /// so a tap straight after `appears` can reach nothing. And a tap on an
    /// element that is covered (a sheet still over it) synthesizes a touch at
    /// {-1, -1} and reports no error, so the failure shows up steps later.
    @MainActor
    func tapWhenSettled(in app: XCUIApplication, timeout: TimeInterval = 10,
                        file: StaticString = #filePath, line: UInt = #line) {
        guard appears(within: timeout) else {
            XCTFail("\(self) never appeared", file: file, line: line)
            return
        }
        guard app.settles(within: timeout) else {
            XCTFail("a presentation was still moving after \(timeout) s; not tapping \(self)", file: file, line: line)
            return
        }
        let deadline = Date().addingTimeInterval(2)
        while !isHittable {
            if Date() >= deadline {
                XCTFail("\(self) is not hittable once settled (covered?)", file: file, line: line)
                return
            }
            Thread.sleep(forTimeInterval: 0.1)
        }
        tap()
    }

    /// Scrolls `container` until this element is on screen. Settings opens as
    /// a half sheet, and Forms and Lists build their rows lazily: a row below
    /// the fold is not in the tree until it is scrolled to. Slow swipes, and
    /// back down if one carried the row past the top.
    ///
    /// A row below the fold does not appear by waiting, only by swiping, so
    /// each step waits half a second rather than the two it used to: that wait
    /// was paid in full before every swipe (F14: ~8 s of Status's commit row).
    @MainActor
    func reveal(scrolling container: XCUIElement, swipes: Int = 8) -> Bool {
        for _ in 0..<swipes {
            if appears(within: 0.5), isHittable { return true }
            if exists, frame.maxY < container.frame.midY {
                container.swipeDown(velocity: .slow)
            } else {
                container.swipeUp(velocity: .slow)
            }
        }
        return appears(within: 2) && isHittable
    }
}

extension XCUIApplication {
    /// Whether no view controller is being presented or dismissed (the app's
    /// `ui-presentation` probe, Testing builds), polled every 100 ms. Pair it
    /// with an element's `appears`: the element proves the sheet began,
    /// `settled` that it finished.
    @MainActor
    func settles(within timeout: TimeInterval) -> Bool {
        let probe = otherElements["ui-presentation"].firstMatch
        let deadline = Date().addingTimeInterval(timeout)
        while !(probe.exists && probe.value as? String == "settled") {
            if Date() >= deadline { return false }
            Thread.sleep(forTimeInterval: 0.1)
        }
        return true
    }

    /// Settings → Status, from the dashboard's gear.
    @MainActor
    func openStatus(file: StaticString = #filePath, line: UInt = #line) -> XCUIElement {
        buttons["settings-button"].firstMatch.tap()
        XCTAssertTrue(navigationBars["Settings"].appears(within: 10), "the gear opens Settings",
                      file: file, line: line)
        let status = buttons["status-button"]
        XCTAssertTrue(status.reveal(scrolling: collectionViews.firstMatch), "Settings has a Status entry",
                      file: file, line: line)
        status.tap()
        let list = collectionViews["diagnostics-list"]
        XCTAssertTrue(list.appears(within: 10), "Status opens", file: file, line: line)
        return list
    }

    /// The value of a Status row (`diag-<label>`), scrolled to and settled
    /// (the cookie rows read "reading…", availability "checking", until they
    /// know); a `<missing …>` marker when there is no such row.
    @MainActor
    func statusRow(_ id: String, in list: XCUIElement) -> String {
        let e = list.descendants(matching: .any).matching(identifier: id).firstMatch
        guard e.reveal(scrolling: list) else { return "<missing \(id)>" }
        // Polled rather than an XCTNSPredicateExpectation, which first looks
        // after a second even when the row has long settled.
        let deadline = Date().addingTimeInterval(10)
        var label = e.label
        while label.contains("reading…") || label.hasSuffix("checking"), Date() < deadline {
            Thread.sleep(forTimeInterval: 0.1)
            label = e.label
        }
        return label
    }
}

/// picker or as that gateway's token sheet.
func testResetAppEndsTheSessionAndStartsOver() async throws {
    let app = launch()
    defer { app.terminate() }
    XCTAssertTrue(element(app, "token-sheet").waitForExistence(timeout: 30))
    try await signIn(app, kind: "cli")

    let before = try await gatewayState()
    confirmInSettings(app, button: "reset-app-button", action: "Reset")
    let firstRun = NSPredicate { object, _ -> Bool in
        guard let app = object as? XCUIApplication else { return false }
        return app.descendants(matching: .any).matching(identifier: "gateway-picker").firstMatch.exists
            || app.descendants(matching: .any).matching(identifier: "token-sheet").firstMatch.exists
    }
    XCTAssertEqual(XCTWaiter().wait(for: [XCTNSPredicateExpectation(predicate: firstRun, object: app)], timeout: 60),
                   .completed, "reset returns to first run: the gateway picker, or the re-found gateway's sign-in")
    let after = try await gatewayState()
    XCTAssertEqual(counter(after, "logouts") - counter(before, "logouts"), 1,
                   "the dashboard session was ended at the gateway first")
    XCTAssertEqual(counter(after, "logout_revocations") - counter(before, "logout_revocations"), 1,
                   "with its refresh cookie: the chain is revoked")
    // No cookie in the new workspace: nothing answers 200. A smoke check
    // only -- the replacement workspace has a new dataStoreUUID, so its
    // store is empty by construction; that the OLD store's cookies are
    // gone from disk is proved by the unreachable-gateway test's
    // relaunch and by test-session.sh's R1 scan (R32 review).
    try await Task.sleep(for: .seconds(6))
    let later = try await gatewayState()
    XCTAssertEqual(counter(later, "auth_me_ok"), counter(after, "auth_me_ok"),
                   "the old session is not restored after a reset")
    XCTAssertEqual(violations(later), 0)
}

// MARK: - F5 §7: switching gateways keeps each one's session

/// Signed in on gw, switched to a second gateway (which asks for its own
/// token), and back: gw's cookies are still in the workspace's one data
/// store, so the page comes back signed in -- no sheet, no redemption.
func testSwitchingBackToAGatewayNeedsNoNewSignIn() async throws {
    let app = launch(extra: ["-UITestKnownGateways", "\(Self.gateway),https://\(Self.secondHost)"],
                     peers: ["gw", "dash"])
    defer { app.terminate() }
    XCTAssertTrue(element(app, "token-sheet").waitForExistence(timeout: 30))
    try await signIn(app, kind: "cli")

    try switchInSettings(app, to: Self.secondHost)
    XCTAssertTrue(element(app, "token-sheet").waitForExistence(timeout: 30),
                  "the second gateway has no session here, so it asks")
    XCTAssertTrue(element(app, "token-sheet-target").label.hasSuffix(Self.secondHost),
                  "for itself: \(element(app, "token-sheet-target").label)")
    element(app, "token-sheet-close").tap()

    let before = try await gatewayState()
    try switchInSettings(app, to: Self.gatewayHost)
    let answered = try await waitForCounter("auth_me_ok", above: counter(before, "auth_me_ok"))
    XCTAssertTrue(answered, "back on gw, the page's session answers again")
    try await Task.sleep(for: .seconds(3))
    XCTAssertFalse(element(app, "token-sheet").exists, "and no sheet asks for a token")
    let after = try await gatewayState()
    XCTAssertEqual(counter(after, "redemptions"), counter(before, "redemptions"), "nothing was redeemed again")
    XCTAssertEqual(violations(after), 0)
}

/// Settings → the switcher's row for `host`.
private func switchInSettings(_ app: XCUIApplication, to host: String,
                              file: StaticString = #filePath, line: UInt = #line) throws {
    let gear = app.buttons["settings-button"].firstMatch
    XCTAssertTrue(gear.waitForExistence(timeout: 10), file: file, line: line)
    if !gear.isHittable {
        let web = app.webViews.firstMatch
        web.coordinate(withNormalizedOffset: CGVector(dx: 0.5, dy: 0.3))
            .press(forDuration: 0.05, thenDragTo: web.coordinate(withNormalizedOffset: CGVector(dx: 0.5, dy: 0.7)))
    }
    gear.tap()
    XCTAssertTrue(app.navigationBars["Settings"].waitForExistence(timeout: 10), file: file, line: line)
    let row = element(app, "gateway-switch-\(host)")
    XCTAssertTrue(row.waitForExistence(timeout: 10) && row.isEnabled, "Settings offers \(host)", file: file, line: line)
    row.tap()
    XCTAssertTrue(app.navigationBars["Settings"].waitForNonExistence(timeout: 10), "the switch closes Settings",
                  file: file, line: line)
}

// MARK: - F5: the page's instance chips at phone width

/// F5 §1a, the measured bug: in portrait the header's left cell is about
/// 180 px and the bundle's own degrade rungs never fire, so the fake's
/// 404 from /api/instances puts the list-failed chip on top of `Local`
/// and the chevron. With the app's gated rule the bar scrolls instead.
func testTheInstanceChipsDoNotOverlapInPortrait() async throws {
    let app = try await signedInDashboard()

        "-TestProxyEndpoint", OfflineHarnessTests.proxyEndpoint,
        "-TestProxyCredential", OfflineHarnessTests.proxyCredential,
        // Keep every test's web data: test-session.sh's R1 scan must see
        // all of it, not only the last test's (M4 review).
        "-UITestKeepWebData",
    ] + extra
    app.launch()
    return app
}

/// Settings → a destructive row (below the fold of the half sheet, so
/// scrolled to) → its confirmation alert's destructive button (R32).
private func confirmInSettings(_ app: XCUIApplication, button id: String, action: String,
                               file: StaticString = #filePath, line: UInt = #line) {
    app.buttons["settings-button"].firstMatch.tap()
    XCTAssertTrue(app.navigationBars["Settings"].waitForExistence(timeout: 10), "the gear opens Settings",
                  file: file, line: line)
    let row = element(app, id)
    XCTAssertTrue(row.reveal(scrolling: app.collectionViews.firstMatch), "Settings has \(id)", file: file, line: line)
    row.tap()
    let confirm = app.alerts.buttons[action].firstMatch
    XCTAssertTrue(confirm.waitForExistence(timeout: 5), "a confirmation first: \(action)", file: file, line: line)
    confirm.tap()
}

/// Polls the gateway until `name` exceeds `floor`.
private func waitForCounter(_ name: String, above floor: Int, timeout: Int = 30) async throws -> Bool {
    for _ in 0..<timeout {
        if counter(try await gatewayState(), name) > floor { return true }
        try await Task.sleep(for: .seconds(1))
    }
    return false
}

private func element(_ app: XCUIApplication, _ id: String) -> XCUIElement {
    app.descendants(matching: .any).matching(identifier: id).firstMatch
}

/// Signs in the way a user does: mint a link at the gateway, put
/// `kirocrew token`-shaped output on the clipboard, tap Paste.
///
/// Also the positive control for `auth_me_ok` (review, 2026-09-23): the
/// sign-out and reset tests hold that counter FLAT -- "nothing answered
/// 200 since" -- and a counter the fake stopped reporting would hold
/// flat forever. A successful sign-in must move it: the app's own check
/// is a 200 from /api/auth/me, which the fake counts as auth_me_ok
/// before it counts app_auth_checks. If this does not move, those flat
/// assertions prove nothing, and this fails first.
private func signIn(_ app: XCUIApplication, kind: String) async throws {
    let minted = try JSONSerialization.jsonObject(
        with: try await Self.post("\(Self.gatewayControl)/__mint?kind=\(kind)")) as? [String: Any]
    let url = try XCTUnwrap(minted?["url"] as? String)
    let link = try XCTUnwrap(minted?["link"] as? String)
    let before = try await gatewayState()
    UIPasteboard.general.string = """
        Dashboard sign-in links (valid 5 minutes):
          http://localhost:5476/?token=\(link)
          \(url)
        """
    let paste = element(app, "token-paste-button").exists
        ? element(app, "token-paste-button")
        : app.buttons["Paste"].firstMatch
    XCTAssertTrue(paste.waitForExistence(timeout: 10), "the sheet offers Paste")
    paste.tap()
    XCTAssertTrue(element(app, "token-sheet").waitForNonExistence(timeout: 30),
                  "signing in dismisses the sheet")
    let after = try await gatewayState()
    XCTAssertGreaterThan(counter(after, "app_auth_checks"), counter(before, "app_auth_checks"),
                         "the APP confirmed the session with its own /api/auth/me")
    XCTAssertGreaterThan(counter(after, "auth_me_ok"), counter(before, "auth_me_ok"),
                         "and that check was a 200, counted as auth_me_ok: the counter the sign-out and reset tests hold flat is live")
}

/// How many times the page has asked for a token in this launch.
private func authRequiredCount(_ app: XCUIApplication) -> Int {
    let marker = element(app, "session-auth-required-count")
    guard marker.waitForExistence(timeout: 5) else { return -1 }
    return Int(marker.label) ?? -1
}

private func typeToken(_ app: XCUIApplication, _ text: String) {
    let field = element(app, "token-input")
    XCTAssertTrue(field.waitForExistence(timeout: 10))
    field.tap()
    field.typeText(text)
    element(app, "token-submit").tap()
}

private func gatewayState() async throws -> [String: Any] {
    try JSONSerialization.jsonObject(with: try await Self.get("\(Self.gatewayControl)/__state")) as? [String: Any] ?? [:]
}

/// A gateway counter. Every name read here is one the fake initialises
/// (fake_gateway.py, `self.counters`), so a missing key is the fake no
/// longer reporting it: a failure, not a zero (review, 2026-09-23 -- an
/// assertion that a counter did not move passes on 0 == 0 forever).
private func counter(_ state: [String: Any], _ name: String,
                     file: StaticString = #filePath, line: UInt = #line) -> Int {
    let counters = state["counters"] as? [String: Any] ?? [:]
    guard let value = counters[name] as? Int else {

    _ = try await Self.post("\(Self.secondControl)/__reset")
    _ = try await Self.post("\(Self.proxyControl)/mode?blackhole=0")
    _ = try await Self.post("\(Self.proxyControl)/open")
}

// MARK: - R22: the native sheet replaces the page's banner

func testSignedOutShowsTheNativeSheetAndHidesThePageBanner() async throws {
    let app = launch()
    defer { app.terminate() }

    let sheet = element(app, "token-sheet")
    XCTAssertTrue(sheet.waitForExistence(timeout: 30), "signed out: the native sheet appears")
    // LabeledContent merges its label into the element: "Signing in to, <host>".
    let target = element(app, "token-sheet-target").label
    XCTAssertTrue(target.hasSuffix(Self.gatewayHost),
                  "the sheet names the gateway it will sign in to (R23); got \(target)")
    element(app, "token-sheet-close").tap()
    XCTAssertTrue(element(app, "session-signin-button").waitForExistence(timeout: 5),
                  "with the sheet closed, the app keeps a way to sign in")
    // Past the 8 s handshake watchdog, so a healthy bridge is shown not to
    // trigger the fallback (M4 review). Positive control for this query:
    // testABrokenBridgeLeavesThePageBannerVisible.
    try await Task.sleep(for: .seconds(11))
    XCTAssertFalse(app.webViews.textFields[Self.bannerPlaceholder].exists,
                   "the page's own banner stays hidden (CSS only), past the watchdog")
    element(app, "session-signin-button").tap()
    XCTAssertTrue(sheet.waitForExistence(timeout: 5), "the button reopens the sheet")
}

/// R22's fallback, and the positive control for the hidden-banner check:
/// with no bridge messages arriving, the app puts the page's banner back
/// after the handshake timeout, and the banner IS visible to this query.
func testABrokenBridgeLeavesThePageBannerVisible() async throws {
    let app = launch(extra: ["-UITestBreakSessionBridge"])
    defer { app.terminate() }

    XCTAssertTrue(app.webViews.textFields[Self.bannerPlaceholder].waitForExistence(timeout: 40),
                  "no handshake: the page's own banner must be shown as the fallback")
    XCTAssertFalse(element(app, "token-sheet").exists, "no bridge, no native sheet")
}

// MARK: - F6: the real bundle connects to nothing but the gateway

/// Every connection the app made this run, as `host:port`, from the stub

/// F3 §7, "The share sheet route (stage 2)" -- fragile by nature: it
/// drives Safari and the system share sheet, whose layout is Apple's.
/// A page is shared from Safari to "Latchkey"; the extension saves it to
/// the App Group inbox and sends nothing; the app, brought back, has the
/// item from `source: extension` and delivers it like any other.
func testTheShareSheetSavesForTheAppAndTheAppSendsIt() async throws {
    let app = try await launchSignedIn()
    defer { app.terminate() }
    let page = "http://127.0.0.1:8481/ext-share-probe"
    let safari = XCUIApplication(bundleIdentifier: "com.apple.mobilesafari")
    safari.launch()
    XCUIDevice.shared.system.open(URL(string: page)!)
    let springboard = XCUIApplication(bundleIdentifier: "com.apple.springboard")
    if springboard.buttons["Open"].waitForExistence(timeout: 2) { springboard.buttons["Open"].tap() }
    XCTAssertTrue(safari.wait(for: .runningForeground, timeout: 15), "Safari is in front")
    try await Task.sleep(for: .seconds(2))

    // Share: a toolbar button on older layouts; on iOS 26 it is in the
    // page menu, the leading button of the address bar.
    let share = safari.buttons.matching(NSPredicate(format: "identifier == 'ShareButton' OR label == 'Share'")).firstMatch
    if !share.waitForExistence(timeout: 3) {
        let menu = safari.buttons.matching(NSPredicate(
            format: "identifier CONTAINS[c] 'PageMenu' OR identifier CONTAINS[c] 'PageFormat' OR label CONTAINS[c] 'Page Menu' OR label == 'More'")).firstMatch
        XCTAssertTrue(menu.waitForExistence(timeout: 5),
                      "Safari's page menu; its buttons: \(safari.buttons.allElementsBoundByIndex.prefix(30).map { "\($0.identifier)|\($0.label)" })")
        menu.tap()
    }
    XCTAssertTrue(share.waitForExistence(timeout: 5),
                  "Safari offers Share; on screen: \(safari.buttons.allElementsBoundByIndex.prefix(40).map { "\($0.identifier)|\($0.label)" })")
    share.tap()

    // The app row. New extensions may sit behind "More" at its end.
    let row = safari.descendants(matching: .any).matching(NSPredicate(format: "label == 'Latchkey'")).firstMatch
    if !row.waitForExistence(timeout: 8) {
        let moreApps = safari.descendants(matching: .any).matching(NSPredicate(format: "label == 'More'")).firstMatch
        if moreApps.exists { moreApps.tap() }
    }
    XCTAssertTrue(row.waitForExistence(timeout: 8), "Latchkey is in the share sheet's app row (the extension is built in)")
    row.tap()

    let save = safari.descendants(matching: .any)["share-capture-save"]
    XCTAssertTrue(save.waitForExistence(timeout: 15), "the extension's sheet offers Save for Latchkey")
    save.tap()
    let saved = safari.descendants(matching: .any)["share-capture-saved"]
    XCTAssertTrue(saved.waitForExistence(timeout: 10), "it says Saved. Open Latchkey to send it.")
    XCTAssertTrue(saved.label.contains("Open Latchkey"), saved.label)
    let before = try await gatewayState()
    XCTAssertEqual(counter(before, "share_posts"), 0, "the extension sent nothing")
    _ = saved.waitForNonExistence(timeout: 5)

    app.activate()
    let source = element(app, "share-item-source")
    XCTAssertTrue(source.waitForExistence(timeout: 30), "the app brings the saved share up")
    XCTAssertEqual(source.label, "extension", "written by the extension, to the group inbox")
    try pick(app, "obsidian")
    element(app, "share-send").tap()
    let awaitedExt = try await lastResult(app)
    XCTAssertEqual(awaitedExt, "sent:obsidian")
    let state = try await gatewayState()
    let message = ((state["posts"] as? [[String: Any]])?.first?["message"] as? String) ?? ""
    XCTAssertTrue(message.contains(page), "the post carries the shared URL: \(message)")
    XCTAssertEqual(violations(state), 0)
}

